function mk(): any {
  const o: any = { name: "X", message: "hi" };
  Error.captureStackTrace(o);
  return o.stack;
}
function wrap(): any { return mk(); }
function main(): void {
  const lines = wrap().split("\n");
  console.log(lines[0], lines[1].includes("at mk "), lines[2].includes("at wrap "));
}
